<?php require_once 'config/functions.php';require_login();$uid=user_id();$month=$_GET['month']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$start=$month.'-01';$days=(int)date('t',strtotime($start));$offset=(int)date('N',strtotime($start));$q=$pdo->prepare('SELECT entry_date,title FROM journals WHERE user_id=? AND entry_date BETWEEN ? AND ?');$q->execute([$uid,$start,$month.'-'.$days]);$entries=[];foreach($q->fetchAll() as $e)$entries[$e['entry_date']][]=$e['title'];$prev=date('Y-m',strtotime($start.' -1 month'));$next=date('Y-m',strtotime($start.' +1 month'));page_header('Calendar');?><div class="card"><div class="row" style="justify-content:space-between"><a class="btn secondary" href="calendar.php?month=<?=$prev?>">← Previous</a><h3><?=date('F Y',strtotime($start))?></h3><a class="btn secondary" href="calendar.php?month=<?=$next?>">Next →</a></div><div class="calendar-grid" style="margin-top:18px"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d):?><div class="day"><?=$d?></div><?php endforeach;for($i=1;$i<$offset;$i++)echo '<div></div>';for($d=1;$d<=$days;$d++):$date=$month.'-'.sprintf('%02d',$d);?><div><strong><?=$d?></strong><?php if(!empty($entries[$date])):foreach($entries[$date] as $title):?><div style="margin-top:5px"><a class="tag" href="journal.php?search=<?=urlencode($title)?>"><?=h(mb_strimwidth($title,0,14,'…'))?></a></div><?php endforeach;endif;?></div><?php endfor;?></div><p class="small">Journal entries are shown on their saved dates.</p></div><?php page_footer();
